function supportDirectory(org){const ids=supportNetwork[org]||[];return `<section class="support-directory"><h2>People you can support</h2><p class="small">Fictional demo connections · Open a profile to choose who you support.</p>${ids.map(id=>`<button class="message-row" data-action="profile:${id}">${avatar(id,false)}<span><strong>${escape(people[id].name)}</strong><small>${escape(supportNeeds[id])} · ${escape(people[id].location)}</small></span>${icon('arrow')}</button>`).join('')||'<p class="small">This organization supports wildlife through its updates below.</p>'}</section>`;}
function profileGiving(id){const f=financeSettings();return `<section class="profile-giving"><h2>Support ${escape(people[id].name.split(' ')[0])}</h2><p>${escape(supportNeeds[id]||'Community support')}</p><div class="profile-gift-row">${btn(icon('heart')+' Give $'+(f.amountCents/100).toFixed(2),'profile-gift:'+id,'primary')}</div><p class="small">Each tap is one demo gift. Growth is earned once per giving day.</p><p id="profile-gift-status" role="status" class="small"></p>${btn('Amount & payment method','finance','text')}</section>`;}
const places=[{name:'The community table',kind:'Culture exchange',detail:'Bring a recipe, a story, or just yourself. A neighborhood gathering to get to know each other.'},{name:'Neighborhood pantry',kind:'Food support',detail:'Ask the community team about food support and collection arrangements.'},{name:'Bamboo community hub',kind:'Private support',detail:'Talk privately with the team about what you need. You do not need to donate first.'}];
const btn=(label,action,cls='')=>`<button type="button" class="button ${cls}" data-action="${action}">${label}</button>`;
