function persist(){try{localStorage.setItem('bamboo-ui-v1',JSON.stringify({...state,version:1}));}catch{toast('Your changes are temporary in this browser.');}}
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function post(p){const author=people[p.author],liked=state.likes.includes(p.id),saved=state.saved.includes(p.id),individual=!!author.individual;return `<article class="post" aria-label="${escape(p.title||'Personal story')}"><div class="post-avatar">${avatar(p.author)}</div><div class="post-column"><div class="post-head"><button class="plain author" data-action="profile:${p.author}"><span>${escape(author.name)}</span><small>${individual?'Community member':'Organization'} · ${escape(p.time||'Just now')}</small></button>${individual?'':`<span class="org-mark" title="Organization account" aria-label="Organization account">${icon('check')}</span>`}<button class="plain post-more" data-action="post-more:${p.id}" aria-label="More options for ${escape(p.title||'this post')}" aria-haspopup="dialog">${icon('plus')}</button></div><div class="post-content"><span class="post-status">${({need:'Seeking support',update:'Community update',story:'Personal story',recipe:'From my kitchen',culture:'Culture & memories'})[p.kind]} · ${author.location}</span>${p.title?`<h2>${escape(p.title)}</h2>`:''}<p>${escape(p.body)}</p>${p.image?`<img class="recipe-cover" src="${escape(p.imageSrc||'assets/community-recipe.png')}" alt="${escape(p.imageAlt||'Illustrative meal of beans and rice')}" loading="lazy" width="${p.imageWidth||1376}" height="${p.imageHeight||768}"${p.imageSrc?' style="aspect-ratio:auto"':''}>`:''}${p.detail?`<p class="post-detail">${escape(p.detail)}</p>`:''}</div><div class="post-actions"><button class="reaction" data-action="like:${p.id}" aria-pressed="${liked}" aria-label="${liked?'Unlike':'Like'} post by ${escape(author.name)}">${icon('heart')} <span>${p.likes+(liked?1:0)}</span></button>${p.author==='me'?`<button class="reaction" data-action="remove:${p.id}">Remove</button>`:`<button class="reaction" data-action="reply:${p.author}" aria-label="Message ${escape(author.name)}">${icon('inbox')} <span>${individual?'Say hello':'Contact'}</span></button>`}${p.author==='me'?'':`<button class="story-give" data-action="give-to:${p.id}" aria-label="Give to ${escape(author.name)}">${icon('heart')} Give</button>`}<button class="reaction save" data-action="save:${p.id}" aria-pressed="${saved}" aria-label="${saved?'Unsave':'Save'} post">${icon('save')}</button></div></div></article>`;}
const profileTabs=()=>`<div class="feed-tabs profile-tabs" aria-label="Profile content">${[['story','Stories'],['recipe','Recipes'],['culture','Culture']].map(([id,label])=>`<button class="filter" data-action="profile-tab:${id}" aria-pressed="${profileTab===id}">${label}</button>`).join('')}</div>`;
function givingStreak(){try{const n=JSON.parse(localStorage.getItem('bamboo-giving-v1'))?.streak;if(Number.isInteger(n)&&n>=0)return n;}catch{}return state.paid?15:14;}
function financeSettings(){let s={};try{s=JSON.parse(localStorage.getItem('bamboo-giving-settings-v1'))||{};}catch{}return {amountCents:Number.isInteger(s.amountCents)&&s.amountCents>0?s.amountCents:10,paymentMethod:['Apple Pay','Card'].includes(s.paymentMethod)?s.paymentMethod:'Demo balance'};}
function financeLinks(){const f=financeSettings();return `<div class="finance-links"><button data-action="finance"><span><strong>Amount per tap</strong><small>Choose how much each gift gives</small></span><b>$${(f.amountCents/100).toFixed(2)}</b></button><button data-action="finance"><span><strong>Payment method</strong><small>Demo preference · no real charge</small></span><b>${escape(f.paymentMethod)}</b></button><button data-action="transactions"><span><strong>Transaction History</strong><small>Every gift, amount, and receipt</small></span>${icon('arrow')}</button></div>`;}
function render(){people.me.name=state.name;people.me.bio=state.bio;people.me.letter=state.name[0]||'A';document.body.dataset.theme=['stone','mist','clay'].includes(state.theme)?state.theme:'stone';document.body.classList.add('reduce-motion');$('streak-trigger').innerHTML=icon('leaf')+`<span>${givingStreak()}</span>`;$('streak-trigger').setAttribute('aria-label',`View your ${givingStreak()} day giving streak`);


let html='';
if(view==='home')html=`<div class="feed-context"><button class="plain city-switch" data-action="map">${icon('pin')} San Diego ${icon('arrow')}</button><span>Demo stories</span></div><div class="feed-tabs" aria-label="Filter community posts">${[['all','For you'],['organizations','Organizations'],['stories','Stories']].map(([id,l])=>`<button class="filter" data-action="filter:${id}" aria-pressed="${filter===id}">${l}</button>`).join('')}</div>${filter==='organizations'?`<section class="support-directory"><h2>Find someone to support</h2><p class="small">Explore a demo organization and meet the people in its network.</p>${Object.keys(supportNetwork).map(id=>btn(escape(people[id].name)+' '+icon('arrow'),'profile:'+id,'wide')).join('')}</section>`:''}${feedPosts().filter(p=>filter==='all'||(filter==='organizations'&&!people[p.author].individual)||(filter==='stories'&&people[p.author].individual)).map(post).join('')}<button class="write-story" data-action="compose" aria-label="Share a personal story">${icon('plus')}<span>Share a story</span></button><div class="feed-end"><span class="end-leaf">${icon('leaf')}</span><p>You’re all caught up.</p><small>Small acts. A city that cares.</small></div>`;
if(view==='giving')html=`<style>body:has(#giving-frame)>.topbar{display:none}body:has(#giving-frame) .page{width:100%;max-width:none;padding:0;margin:0;border:0}body:has(#giving-frame) #main{height:calc(100dvh - 80px - env(safe-area-inset-bottom))}#giving-frame{display:block;width:100%;height:calc(100dvh - 80px - env(safe-area-inset-bottom));border:0;background:#e8ede1}</style><iframe id="giving-frame" src="giving.html?embedded=1&v=hearts-3${givingTarget?'&amp;'+new URLSearchParams(givingTarget).toString():''}" title="Bamboo giving and growth — local demo"></iframe>`;
if(view==='inbox')html=`<div class="section-heading"><div><h1>Your conversations</h1><p>A private way to meet a neighbor or reach an organization.</p></div></div><section class="panel">${[...new Set(['maria','lin','team','table','roots','wild',...state.friends,...state.messages.map(m=>m.to)])].filter(w=>people[w]).map(w=>`<button class="message-row" data-action="chat:${w}">${avatar(w,false)}<span><strong>${people[w].name}</strong><small>${people[w].individual?'Community member':'Organization'} · ${people[w].location}</small></span>${icon('arrow')}</button>`).join('')}<p class="small" style="margin-top:20px">Demo conversations. Messages stay in this browser.</p></section>`;
if(view==='chat')html=`<section class="panel stack">${btn('← Back to inbox','inbox','text')}<div class="row">${avatar(chat,false)}<h2>${people[chat].name}</h2></div><p class="small">Your first message is a request. This preview does not deliver messages to anyone.</p>${state.messages.filter(m=>m.to===chat).map(m=>`<div class="chat-bubble">${escape(m.body)}${m.postId?btn('Open shared post','open-shared:'+m.postId,'text'):''}<p class="small">Local demo request</p></div>`).join('')}<form id="message-form" class="form"><label>Your message<textarea name="body" maxlength="500" required placeholder="Hello, I’d like to ask about…">${escape(chatDrafts[chat]||'')}</textarea></label><button class="button primary">Preview message request ${icon('arrow')}</button></form></section>`;
if(view==='you')html=`<section class="panel stack"><div class="row">${avatar('me',false)}<div><h1>${escape(state.name)}</h1><p class="small">San Diego · Community member</p></div></div><p>${escape(state.bio)}</p><div class="row wrap">${btn('Finance','finance','primary wide')}${btn('Streak widget','widget')}${btn('Edit profile','edit-profile')}${btn('Saved posts','saved')}${btn(icon('settings')+' Settings','settings')}</div></section><section class="hero"><div class="hero-circle"></div><div class="hero-copy"><span class="eyebrow">Your little grove</span><h1>${givingStreak()} days<br>of showing up.</h1><p>Your contribution matters, whatever its size.</p>${btn('See your growth','growth','soft')}</div><img class="bamboo-growth ${state.motion?'is-idle':''}" src="assets/days/day-${state.paid?'15':'14'}.png" alt="Your growing bamboo"></section><div class="row wrap">${btn('Community','wall')}${btn('I need a helping hand','help')}</div><div class="profile-content-head"><h2>Your corner</h2>${btn('Share something','compose','text')}</div>${profileTabs()}${posts().filter(p=>p.author==='me'&&p.kind===profileTab).map(post).join('')||'<p class="empty">A space for your stories, recipes, and traditions.</p>'}`;
if(view==='you'&&state.reposts.length)html+='<h2>Reposts</h2>'+posts().filter(p=>state.reposts.includes(p.id)).map(post).join('');
if(view==='profile'){const person=people[selectedProfile];html=`<section class="panel stack">${btn('← Back to the community','home','text')}<div class="row">${avatar(selectedProfile,false)}<div><h1>${escape(person.name)}</h1><p class="small">${person.individual?'Community member':'Organization'} · ${person.location}</p></div></div><p>${escape(person.bio)}</p>${btn((person.individual?'Say hello':'Contact organization')+' '+icon('inbox'),'chat:'+selectedProfile,'primary')}</section>${person.individual?profileGiving(selectedProfile):supportDirectory(selectedProfile)}${person.individual?profileTabs():''}${posts().filter(p=>p.author===selectedProfile&&(!person.individual||p.kind===profileTab)).map(post).join('')||'<p class="empty">Nothing shared here yet.</p>'}`;}
if(view==='wall'||view==='map')html='';
if(view==='community')html=window.BambooLocation.render();
if(view==='saved')html=`<section class="panel stack"><h1>Saved posts</h1>${btn('← Back to your profile','you','text')}</section>${posts().filter(p=>state.saved.includes(p.id)).map(post).join('')||'<p class="empty">Save a post to find it here later.</p>'}`;
if(view==='widget')html=`<section class="panel stack"><h1>Your streak widget</h1><p class="small">Live demo streak · web preview, not an installed phone widget.</p>${btn('← Back to your profile','you','text')}</section><iframe class="widget-frame" src="widget.html?live=1" title="Your Bamboo streak widget"></iframe>`;
if(view==='settings')html=`<section class="panel stack"><h1>Account Settings</h1><h2>Finance</h2>${financeLinks()}${btn("Your community","community")}${state.wall?btn("Remove my public avatar","wall-off"):givingStreak()>=15?btn("Choose to join the wall","wall-consent"):"<p class=small>At 15 days, you can choose to join the wall.</p>"}<h3>Background</h3><p class="small">A quiet canvas. Choose the one that feels right.</p><div class="theme-options">${[['stone','Bamboo green'],['mist','Morning mist'],['clay','Soft clay']].map(([id,name])=>`<button class="theme-choice" data-action="theme:${id}" aria-pressed="${(state.theme||'stone')===id}"><span class="theme-swatch"></span>${name}</button>`).join('')}</div><hr class="divider"><p>No daily donation reminders.</p><p class="small">The opening lasts 1.8 seconds. Reduced-motion preferences skip it.</p>${btn('Replay opening animation','replay-intro')}${btn('View community wallpaper','wall')}${btn('← Back to your profile','you','text')}</section>`;
if(view==='finance'){const f=financeSettings();html=`<section class="panel stack finance-panel">${btn('← Account Settings','settings','text')}<h1>Finance</h1><form id="finance-form" class="form"><label>Amount per tap (USD)<input name="amount" id="finance-amount" inputmode="decimal" value="${(f.amountCents/100).toFixed(2)}" required></label><div class="amounts">${[10,50,100,500].map(n=>btn('$'+(n/100).toFixed(2),'finance-amount:'+n,'soft')).join('')}</div><p class="small">Each donation tap gives this amount. This is not a daily spending limit.</p><fieldset class="payment-options"><legend>Payment method</legend>${['Demo balance','Apple Pay','Card'].map(method=>`<label><input type="radio" name="payment" value="${method}" ${f.paymentMethod===method?'checked':''}>${method}<span>Demo</span></label>`).join('')}</fieldset><p class="small">Payment methods are preview choices only. No card details are collected and no money is charged.</p><p id="finance-error" class="error" role="alert"></p><button class="button primary wide">Save finance settings</button></form>${btn('Transaction History '+icon('arrow'),'transactions','wide finance-history')}</section>`;}
if(view==='transactions'){let receipts=[];try{receipts=JSON.parse(localStorage.getItem('bamboo-giving-v1'))?.receipts||[];}catch{}html=`<section class="panel stack"><h1>Transaction History</h1>${btn('← Account Settings','settings','text')}<p class="small">Demo gifts only. No real charges.</p>${receipts.length?receipts.slice().reverse().map(r=>`<div class="transaction-row"><strong>${escape(r.recipient?.name||'San Diego community pool')}</strong><span>$${(r.amountCents/100).toFixed(2)}</span><small>${r.createdAt?escape(new Date(r.createdAt).toLocaleString('en-US')):'Earlier demo gift'} · Completed</small></div>`).join(''):'<p>No gifts yet. Start with a story in your community.</p>'}</section>`;}
if(view==='help')html=`<section class="panel stack"><span class="eyebrow">A little support</span><h1>You belong here, too.</h1><p>Tell the community team what would help. You don’t need to donate or tell your story publicly.</p>${btn('Talk privately with the team','chat:team','primary')}<p class="small">This is a local demo. Requests are not sent to a support organization.</p></section>`;
let content=$('view-content');if(!content){content=document.createElement('div');content.id='view-content';content.style.display='contents';$('main').prepend(content);}content.innerHTML=html;if(wallFrame)wallFrame.hidden=true;if(view==='wall'||view==='map')communityFrame().hidden=false;renderSidebar();renderBottomNav();}
function renderBottomNav(){const current=view==='wall'?'map':view==='chat'?'inbox':['settings','saved','widget','community','transactions','finance'].includes(view)?'you':view==='profile'?'home':view;const nav=$('bottom-nav');if(nav)nav.innerHTML=[['home','Home'],['map','Community'],['giving','Grove'],['inbox','Messages'],['you','You']].map(([id,label])=>`<button type="button" data-action="${id}" ${current===id?'aria-current="page"':''}>${icon(id==='map'?'leaf':id)}<span>${label}</span></button>`).join('');}
function renderSidebar(){const current=view==='chat'?'inbox':view==='profile'?'home':view;$('drawer-content').innerHTML=`<div class="drawer-head"><h2 id="drawer-title">Your community</h2><button class="header-control" data-action="menu-close" aria-label="Close navigation">${icon('close')}</button></div><button class="drawer-profile" data-action="you">${avatar('me',false)}<span><strong>${escape(state.name)}</strong><small>Community member</small></span>${icon('arrow')}</button><nav aria-label="Main navigation">${[['home','home','Home'],['map','leaf','Community'],['giving','giving','Your grove'],['inbox','inbox','Messages'],['saved','save','Saved posts'],['you','you','Your profile'],['community','pin','Your community'],['settings','settings','Account Settings']].map(([id,i,label])=>`<button class="drawer-link" data-action="${id}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span></button>`).join('')}</nav><div class="drawer-bottom">${btn('Share a personal story','compose','wide')}${btn('Give a little '+icon('heart'),'donate','primary wide')}${btn('I need a helping hand','help','text wide')}<p>Any amount. One shared city pool.</p><button class="plain demo-note" data-action="about">About Bamboo · Demo preview</button></div>`;}
function closeMenu(){if($('sidebar').open)$('sidebar').close();$('menu-trigger').setAttribute('aria-expanded','false');}
$('sidebar').addEventListener('close',()=>{$('menu-trigger').setAttribute('aria-expanded','false');});
$('sidebar').addEventListener('click',e=>{if(e.target===$('sidebar')){const r=$('sidebar').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeMenu();}});
function navigate(next){closeMenu();view=next;history.pushState({view,selectedProfile,selectedPlace,chat,givingTarget},'', '#'+next);render();$('main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
window.addEventListener('popstate',e=>{closeMenu();if($('dialog').open)$('dialog').close();const p=e.state||{};view=p.view||'home';selectedProfile=p.selectedProfile||'table';selectedPlace=p.selectedPlace||0;chat=p.chat||'team';givingTarget=p.givingTarget||null;render();});
function modal(content){closeMenu();$('dialog-content').innerHTML=content;$('dialog').showModal();}
const heading=t=>`<div class="dialog-head"><h2 id="dialog-title">${t}</h2><button class="close" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>`;

function compose(kind='story'){draftKind=kind;modal(heading('A little piece of you.')+`<form id="post-form" class="form"><p class="muted">A story, a recipe, or a moment that matters.</p><label>What are you sharing?<select name="kind">${[['story','A little story'],['recipe','A family recipe'],['culture','Culture & memories']].map(([id,l])=>`<option value="${id}" ${id===kind?'selected':''}>${l}</option>`).join('')}</select></label><label>Your post<textarea name="body" maxlength="1200" required placeholder="In my family, we always…">${escape(draft)}</textarea></label><p class="small">Posted publicly as ${escape(state.name)} in this local demo. Sharing is always optional.</p><button class="button primary">Share with the community ${icon('arrow')}</button></form>`);}
function donate(){if(state.paid){modal(heading('Your kindness is already here.')+`<div class="success"><img class="bamboo-growth" src="assets/days/day-15.png" alt="Day 15 bamboo"><h2>15 days of growing good.</h2><p>Today’s demo donation is complete. More money never makes your bamboo grow faster.</p></div>${btn('Back to the community','close','wide')}`);return;}modal(heading('A little is enough.')+`<form id="donate-form" class="form"><div class="row"><img src="assets/bamboo-bank.png" alt="Community bamboo bank" width="100" height="100"><p class="muted">Every little bit joins the San Diego community pool.</p></div><div class="amounts">${[10,50,100].map(n=>btn('$'+(n/100).toFixed(2),'amount:'+n,'soft')).join('')}</div><label>Your amount (USD)<input name="amount" id="donation-amount" inputmode="decimal" value="${escape(donationRaw)}" required></label><p class="error" id="donate-error" role="alert"></p><p class="small">Single demo donation. No real charge. Actual settlement and fees are not implemented.</p><button class="button primary">Review my kindness ${icon('arrow')}</button></form>`);}
document.addEventListener('click',async e=>{const t=e.target.closest('[data-action]');if(!t)return;const a=t.dataset.action;
if(a.startsWith('post-more:')){const p=posts().find(p=>p.id===a.slice(10));if(!p)return;modal(heading('Share a little good')+`<div class="stack">${btn(state.reposts.includes(p.id)?'Undo repost':'Repost','repost:'+p.id,'wide')}${btn('Send to someone','send-post:'+p.id,'wide')}${p.author!=='me'&&people[p.author].individual?btn(state.friends.includes(p.author)?'Cancel friend request':'Add friend','friend:'+p.author,'wide'):''}<p class="small">Local demo. Reposts and requests stay in this browser.</p></div>`);return;}
if(a.startsWith('repost:')){const id=a.slice(7);if(!posts().some(p=>p.id===id))return;const exists=state.reposts.includes(id);state.reposts=exists?state.reposts.filter(x=>x!==id):[...state.reposts,id];persist();$('dialog').close();render();toast(exists?'Repost removed.':'Reposted to your profile in this demo.');return;}
if(a.startsWith('friend:')){const id=a.slice(7);if(!people[id]?.individual||id==='me')return;const exists=state.friends.includes(id);state.friends=exists?state.friends.filter(x=>x!==id):[...state.friends,id];persist();$('dialog').close();toast(exists?'Friend request cancelled.':'Friend request saved locally. Not delivered.');return;}
if(a.startsWith('send-post:')){const id=a.slice(10);if(!posts().some(p=>p.id===id))return;modal(heading('Send to someone')+`<p class="small">Choose a person. This demo saves the shared post locally.</p><div class="stack">${Object.keys(people).filter(id=>id!=='me'&&people[id].individual).sort((a,b)=>Number(state.friends.includes(b))-Number(state.friends.includes(a))).map(w=>btn(escape(people[w].name),'send-to:'+id+':'+w,'wide')).join('')}</div>`);return;}
if(a.startsWith('send-to:')){const [,id,to]=a.split(':'),p=posts().find(p=>p.id===id);if(!p||!people[to]||to==='me')return;state.messages.push({to,body:'Shared a post: '+(p.title||p.body.slice(0,80)),postId:id});persist();$('dialog').close();toast('Post saved in your demo conversation. Not delivered.');return;}
if(a.startsWith('open-shared:')){const p=posts().find(p=>p.id===a.slice(12));if(p)modal(heading('Shared post')+post(p));else toast('This post is no longer available.');return;}
if(a.startsWith('profile-gift:')){const id=a.slice(13);if(!people[id]?.individual||id==='me'||t.disabled)return;const status=$('profile-gift-status'),amount=financeSettings().amountCents;t.disabled=true;t.setAttribute('aria-busy','true');if(status)status.textContent='Sending your demo gift…';try{const result=await window.BambooGivingAdapter.donate({amountCents:amount,idempotencyKey:crypto.randomUUID(),recipient:{id,name:people[id].name,storyId:posts().find(p=>p.author===id&&p.kind==='story')?.id||''}});if(status?.isConnected)status.textContent=`$${(amount/100).toFixed(2)} for ${people[id].name}. Saved in Transaction History.`;const destination=document.querySelector('#bottom-nav [data-action="giving"] .icon');if(t.isConnected&&destination){const heart=document.createElement('span');heart.className='profile-flying-heart';heart.textContent='♥';heart.setAttribute('aria-hidden','true');document.body.append(heart);const from=t.getBoundingClientRect(),to=destination.getBoundingClientRect();heart.style.left=from.left+from.width/2+'px';heart.style.top=from.top+from.height/2+'px';if(heart.animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const effect=heart.animate([{transform:'translate(-50%,-50%) scale(.7)',opacity:1},{transform:`translate(calc(-50% + ${to.left+to.width/2-from.left-from.width/2}px), calc(-50% + ${to.top+to.height/2-from.top-from.height/2}px)) scale(.25)`,opacity:0}],{duration:650,easing:'cubic-bezier(.2,.8,.3,1)'});effect.onfinish=()=>heart.remove();}else heart.remove();}$('streak-trigger').innerHTML=icon('leaf')+`<span>${result.streak}</span>`;$('streak-trigger').setAttribute('aria-label',`View your ${result.streak} day giving streak`);}catch{if(status?.isConnected)status.textContent='Gift did not complete. Please try again.';}finally{t.disabled=false;t.setAttribute('aria-busy','false');}return;}
if(a.startsWith('finance-amount:')){$('finance-amount').value=(Number(a.split(':')[1])/100).toFixed(2);return;}
if(a==='menu'){renderSidebar();$('sidebar').showModal();$('menu-trigger').setAttribute('aria-expanded','true');return;}
if(a==='menu-close'){closeMenu();return;}
if(a==='replay-intro'){window.BambooIntro?.play();return;}
if(a==='giving')givingTarget=null;
if(['home','map','giving','inbox','you','settings','wall','help','saved','widget','community','transactions','finance'].includes(a)){navigate(a);return;}
if(a.startsWith('theme:')){state.theme=a.split(':')[1];persist();render();toast('Background saved.');return;}
if(a==='compose'||a.startsWith('compose:')){compose(a.split(':')[1]||draftKind);return;}
if(a.startsWith('remove:')){const id=a.slice(7);removedPost=state.posts.find(p=>p.id===id);if(removedPost){state.posts=state.posts.filter(p=>p.id!==id);persist();render();modal(heading('Post removed.')+`<p>Your post is no longer in the feed.</p>${btn('Undo removal','undo-remove','wide')}${btn('Done','close','text wide')}`);}return;}
if(a==='undo-remove'&&removedPost){state.posts.unshift(removedPost);removedPost=null;persist();$('dialog').close();render();toast('Post restored.');return;}
if(a.startsWith('profile-tab:')){profileTab=a.split(':')[1];render();return;}
if(a.startsWith('give-to:')){const p=posts().find(p=>p.id===a.slice(8));if(p&&p.author!=='me'){givingTarget={recipient:p.author,name:people[p.author].name,story:p.id};navigate('giving');}return;}
if(a==='close'){$('dialog').close();return;}

if(a.startsWith('filter:')){filter=a.split(':')[1];render();return;}
if(a.startsWith('like:')||a.startsWith('save:')){const [action,id]=a.split(':'),key=action==='like'?'likes':'saved';state[key]=state[key].includes(id)?state[key].filter(v=>v!==id):[...state[key],id];persist();render();if(action==='save')toast(state.saved.includes(id)?'Saved to this browser.':'Removed from saved posts.');return;}


if(a.startsWith('profile:')){selectedProfile=a.split(':')[1];profileTab='story';navigate(selectedProfile==='me'?'you':'profile');return;}
if(a.startsWith('chat:')||a.startsWith('reply:')){chat=a.split(':')[1];if(chat==='me'){toast('This is your profile.');return;}navigate('chat');return;}
if(a.startsWith('place:')){selectedPlace=Number(a.split(':')[1]);render();return;}
if(a==='donate'){donate();return;}
if(a.startsWith('amount:')){donationRaw=(Number(a.split(':')[1])/100).toFixed(2);$('donation-amount').value=donationRaw;return;}
if(a==='pay-fail'){donate();$('donate-error').textContent='Payment did not complete. No money or streak was added. You can retry.';return;}
if(a==='pay'){if(state.paid)return;state.paid=true;state.amount=donationCents;try{const old=JSON.parse(localStorage.getItem('bamboo-giving-v1'))||{streak:14,growthDays:14,receipts:[],receivedCents:0};const date=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),fresh=old.lastGivingDate!==date,gap=old.lastGivingDate?(Date.parse(date)-Date.parse(old.lastGivingDate))/86400000:1;localStorage.setItem('bamboo-giving-v1',JSON.stringify({...old,lastGivingDate:date,streak:fresh?(gap===1?old.streak+1:1):old.streak,growthDays:old.growthDays+(fresh?1:0),receivedCents:(old.receivedCents||0)+donationCents,receipts:[...(old.receipts||[]),{id:crypto.randomUUID(),amountCents:donationCents,recipient:null,createdAt:new Date().toISOString(),status:'completed'}]}));}catch{}persist();render();$('dialog-content').innerHTML=heading('A little kindness. A new leaf.')+`<div class="success"><img class="bamboo-growth is-idle" src="assets/days/day-15.png" alt="Your bamboo grew to day 15"><h2>15 day streak!</h2><p>$${(state.amount/100).toFixed(2)} joined the demo community pool.</p></div><p class="small" style="margin:18px 0">You can now choose to join the city kindness wall. Your photo is never shared automatically.</p>${btn('Choose whether to join','wall-consent','primary wide')}${btn('Keep it private for now','close','text wide')}`;return;}
if(a==='growth'){modal(heading('Your kindness is taking root.')+`<div class="success"><img class="bamboo-growth ${state.motion?'is-idle':''}" src="assets/days/day-${state.paid?'15':'14'}.png" alt="Your bamboo"><h2>${givingStreak()} day giving streak</h2><p>${state.paid?'Today is complete. Thank you.':'A little kindness goes a long way.'}</p></div><div class="ledger"><span>15 days</span><strong>Optional wall invitation</strong><span>14 days</span><strong>One bamboo · up to six</strong></div><p class="small">Every amount grows equally. Likes and messages do not change your giving streak.</p>${state.paid?'':btn('Give a little','donate','primary wide')}`);return;}
if(a==='wall-consent'){if(givingStreak()<15){toast('An invitation unlocks at 15 days.');return;}if($('dialog').open)$('dialog').close();modal(heading('Be part of the picture?')+`<form id="wall-form" class="form"><p>Everyone’s avatar is the same size. We never display donation amounts.</p><label class="checkbox"><input name="consent" type="checkbox" required><span>I choose to show my name and initial on the community wall. I can remove them later.</span></label><button class="button primary">Join the demo wall</button>${btn('Stay private','close','text')}</form>`);return;}
if(a==='wall-off'){state.wall=false;persist();render();toast('Your avatar is private. Your contribution still counts.');return;}
if(a==='edit-profile'){modal(heading('Make yourself at home.')+`<form id="profile-form" class="form"><label>Your name<input name="name" maxlength="40" value="${escape(state.name)}" required></label><label>A little about you<textarea name="bio" maxlength="240">${escape(state.bio)}</textarea></label><button class="button primary">Save profile</button></form>`);return;}


if(a==='about'){modal(heading('A little good, every day.')+'<p>Bamboo brings small donations, shared stories, and community care together. All funds join one city pool.</p><p class="small" style="margin-top:15px">Hackathon UI demo. Fictional members, generated recipe image, simulated funds. No real transactions or messages.</p>');}
});
document.addEventListener('input',e=>{if(e.target.form?.id==='post-form'&&e.target.name==='body')draft=e.target.value;if(e.target.form?.id==='message-form')chatDrafts[chat]=e.target.value;if(e.target.id==='donation-amount')donationRaw=e.target.value;});

document.addEventListener('change',e=>{if(e.target.form?.id==='post-form'&&e.target.name==='kind')draftKind=e.target.value;});
document.addEventListener('submit',e=>{const form=e.target;if(!['post-form','donate-form','profile-form','message-form','wall-form','finance-form'].includes(form.id))return;e.preventDefault();if(!form.checkValidity())return;const data=new FormData(form);

if(form.id==='post-form'){const body=String(data.get('body')).trim();if(!body){toast('Write something before sharing.');return;}if(!['story','recipe','culture'].includes(String(data.get('kind')))){toast('Choose a story, recipe, or cultural memory.');return;}state.posts.unshift({id:'p'+Date.now()+'-'+Math.random().toString(36).slice(2,7),author:'me',kind:String(data.get('kind')),body,likes:0,time:'Just now'});draft='';filter='all';persist();$('dialog').close();profileTab=String(data.get('kind'));navigate(profileTab==='story'?'home':'you');toast('Your story is part of the community. Giving streak unchanged.');}
if(form.id==='donate-form'){const raw=String(data.get('amount')).trim(),n=Number(raw);if(!/^\d+(\.\d{1,2})?$/.test(raw)||n<.01||n>10000){$('donate-error').textContent='Enter $0.01–$10,000, with up to two decimal places.';return;}donationCents=Math.round(n*100);$('dialog-content').innerHTML=heading('A little kindness, together.')+`<div class="ledger"><span>Your single donation</span><strong>$${n.toFixed(2)}</strong><span>Goes to</span><strong>San Diego shared pool</strong></div><p class="small" style="margin:18px 0">Demo only. No real money will be charged.</p>${btn('Simulate successful donation','pay','primary wide')}${btn('Simulate failed donation','pay-fail','text wide')}${btn('Change amount','change-amount','text wide')}`;}
if(form.id==='profile-form'){const name=String(data.get('name')).trim();if(!name){toast('Enter a display name.');return;}state.name=name;state.bio=String(data.get('bio'));persist();$('dialog').close();render();toast('Profile updated.');}
if(form.id==='finance-form'){const raw=String(data.get('amount')).trim(),amount=Number(raw),method=String(data.get('payment'));if(!/^\d+(\.\d{1,2})?$/.test(raw)||amount<.01||amount>10000||!['Demo balance','Apple Pay','Card'].includes(method)){$('finance-error').textContent='Enter $0.01–$10,000 with up to two decimal places, and select a payment method.';return;}try{localStorage.setItem('bamboo-giving-settings-v1',JSON.stringify({amountCents:Math.round(amount*100),paymentMethod:method}));toast('Finance settings saved. Applies to your next gift.');}catch{$('finance-error').textContent='Could not save. Please try again.';return;}render();}
if(form.id==='message-form'){const body=String(data.get('body')).trim();if(!body){toast('Write a message first.');return;}chatDrafts[chat]='';state.messages.push({to:chat,body});persist();render();toast('Demo request saved locally. Not sent to anyone.');}
if(form.id==='wall-form'&&givingStreak()>=15){state.wall=true;persist();$('dialog').close();navigate('wall');toast('You chose to join the demo wall.');}
});
document.addEventListener('click',e=>{if(e.target.closest('[data-action="change-amount"]')){$('dialog').close();donate();}});
document.querySelector('.brand').addEventListener('click',e=>{e.preventDefault();navigate('home');});
if(location.hash==='#organizations')filter='organizations';
if(['#wall','#map'].includes(location.hash))view=location.hash.slice(1);
history.replaceState({view},'', '#'+view);
render();

// The giving page owns its scene; reuse the app drawer for navigation.
window.addEventListener('message',event=>{const frame=document.getElementById('giving-frame');if(event.origin!==location.origin||!frame||event.source!==frame.contentWindow)return;if(event.data?.type==='bamboo:giving-navigation'){if(event.data.discover)filter='organizations';navigate('home');}});

window.addEventListener('storage',e=>{if(e.key==='bamboo-giving-v1'&&view!=='giving')render();});

// Warm the shared image sheets after the first paint, without blocking app launch.
const warmImages=()=>{communityFrame();for(const src of ['assets/community-photo-9.jpg','assets/community-photo-13.jpg','assets/community-photo-10.jpg']){const img=new Image();img.src=src;if(img.decode)img.decode().catch(()=>{});}};
if(window.requestIdleCallback)requestIdleCallback(warmImages,{timeout:2000});else setTimeout(warmImages,250);
document.addEventListener('pointerup',event=>{const button=event.target.closest('button');if(!button||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;button.classList.remove('tap-feedback');requestAnimationFrame(()=>button.classList.add('tap-feedback'));});
document.addEventListener('animationend',event=>{if(event.animationName==='tap-feedback')event.target.classList.remove('tap-feedback');});
